-- V2.1 local activation uses an immutable bundled revision.
-- Only additive reference keys required by workout FK; no history, draft or shared template updates.
begin;
set local lock_timeout = '5s';
insert into public.exercise_library (key,name,muscles,steps,mistakes,youtube_url,active) values
('pallof_press','Жим Палофа',array['косые мышцы живота','поперечная мышца живота','мышцы корпуса']::text[],array['Закрепи рукоять на уровне груди. Встань боком к блоку, стопы на ширине плеч, колени немного согнуты.','Держи рукоять двумя руками перед грудью. Напряги живот, сохрани таз и плечи направленными вперёд.','Плавно выпрями руки перед собой, сопротивляясь развороту к блоку. Не задерживай дыхание.','Верни руки к груди. Выполни 10–12 повторений, затем повернись другим боком и повтори.','Один записанный подход означает обе стороны. При разном числе повторов запиши меньшее и добавь пояснение в заметку самочувствия.']::text[],array['Не разворачивай таз или плечи вслед за тросом.','Не наклоняйся в сторону и не прогибай поясницу.','Не выбирай вес, который мешает удержать корпус.']::text[],null,true),
('cable_hip_extension','Разгибание бедра назад в кроссовере',array['большая ягодичная','задняя поверхность бедра','мышцы корпуса как стабилизаторы']::text[],array['Закрепи манжету на щиколотке и пристегни к нижнему блоку. Встань лицом к тренажёру и держись за опору.','Слегка согни опорное колено. Удерживай таз ровно, живот напряжён; допустим небольшой наклон корпуса от тазобедренных суставов.','Плавно отведи рабочую ногу назад движением в тазобедренном суставе. Колено сохраняет небольшой постоянный сгиб.','Остановись до прогиба в пояснице и поворота таза. Верни ногу под контролем.','Выполни 12–15 повторений каждой ногой. Один записанный подход — обе ноги; при разнице запиши меньшее число повторов.']::text[],array['Не прогибай поясницу ради большей амплитуды.','Не разворачивай таз и не раскачивай корпус.','Не бросай груз и не отводи ногу рывком.']::text[],null,true)
on conflict (key) do nothing;
commit;
